// (app) layout: guards the group, mounts the sync provider and renders the visual shell (stream B).
// requireSessionInfo() is requireUser() plus the user's name/image for the avatar: one session lookup, same redirect.
import type { Metadata } from "next";
import type { ReactNode } from "react";
import { SyncProvider } from "@/client/sync";
import { AppShell } from "@/components/shell/AppShell";
import { requireSessionInfo } from "@/server/auth/session";

// iOS splash screens (portrait; files generated by tools/pwa/generate.ts). `media` picks the device by CSS size + pixel ratio.
const SPLASH: [number, number, number][] = [
  [440, 956, 3],
  [402, 874, 3],
  [430, 932, 3],
  [393, 852, 3],
  [428, 926, 3],
  [390, 844, 3],
  [414, 896, 3],
  [414, 896, 2],
  [375, 812, 3],
  [414, 736, 3],
  [375, 667, 2],
];

export const metadata: Metadata = {
  icons: {
    icon: [{ url: "/favicon.ico" }, { url: "/icons/icon-192.png", sizes: "192x192", type: "image/png" }],
    apple: [{ url: "/apple-touch-icon.png", sizes: "180x180" }],
  },
  // Replaces the root `appleWebApp` wholesale (metadata merges per key), so the root values are repeated here.
  appleWebApp: {
    capable: true,
    title: "Overload",
    statusBarStyle: "black-translucent",
    startupImage: SPLASH.map(([w, h, dpr]) => ({
      url: `/splash/${w * dpr}x${h * dpr}.png`,
      media: `(device-width: ${w}px) and (device-height: ${h}px) and (-webkit-device-pixel-ratio: ${dpr}) and (orientation: portrait)`,
    })),
  },
};

export default async function AppLayout({ children }: { children: ReactNode }) {
  const { ctx, user } = await requireSessionInfo();
  return (
    <SyncProvider userId={ctx.id}>
      <AppShell user={{ name: user.name, image: user.image }}>{children}</AppShell>
    </SyncProvider>
  );
}
